def cmp_semver(a, b):
    def parse(v):
        # Remove build metadata (everything after '+')
        v = v.split('+')[0]
        # Split into major, minor, patch
        parts = v.split('.')
        major, minor, patch = int(parts[0]), int(parts[1]), int(parts[2])

        # Handle pre-release
        prerelease = []
        if '-' in v:
            pre_part = v.split('-', 1)[1]
            identifiers = pre_part.split('.')
            for ident in identifiers:
                try:
                    prerelease.append((True, int(ident)))
                except ValueError:
                    prerelease.append((False, ident))
        return (major, minor, patch, prerelease)

    pa = parse(a)
    pb = parse(b)

    # Compare major, minor, patch
    for i in range(3):
        if pa[i] != pb[i]:
            return -1 if pa[i] < pb[i] else 1

    # Compare pre-release
    pra, pbr = pa[3], pb[3]

    # If neither has pre-release, they are equal
    if not pra and not pbr:
        return 0
    # If only 'a' has pre-release, 'a' < 'b' (pre-release sorts before release)
    if not pra:
        return 1
    # If only 'b' has pre-release, 'a' > 'b'
    if not pbr:
        return -1

    # Compare identifiers
    min_len = min(len(pra), len(pbr))
    for i in range(min_len):
        is_num_a, val_a = pra[i]
        is_num_b, val_b = pbr[i]

        # Numeric identifiers sort before alphanumeric ones
        if is_num_a != is_num_b:
            return -1 if is_num_a else 1

        # If types are the same, compare values
        if is_num_a:
            if val_a != val_b:
                return -1 if val_a < val_b else 1
        else:
            if val_a != val_b:
                return -1 if val_a < val_b else 1

    # If all compared identifiers are equal, the longer list is greater
    if len(pra) < len(pbr):
        return -1
    elif len(pra) > len(pbr):
        return 1
    else:
        return 0
